<?php require __DIR__.'/config.php';$u=require_login();$b=require_business();if(!can('staff')){http_response_code(403);exit('Forbidden');}$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($action==='create'){if($err=plan_limit_error((int)$b['id'],'staff'))throw new RuntimeException($err);$s=$pdo->prepare("INSERT INTO users(business_id,name,email,password_hash,role,status,created_at) VALUES(?,?,?,?,?,'active',NOW())");$s->execute([$b['id'],trim($_POST['name']),trim($_POST['email']),password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['role']]);flash('Staff account created.');}elseif($action==='update'){$id=(int)$_POST['id'];$role=$_POST['role'];$status=$_POST['status'];$s=$pdo->prepare("UPDATE users SET role=?,status=? WHERE id=? AND business_id=? AND role NOT IN ('owner','admin','super_admin')");$s->execute([$role,$status,$id,$b['id']]);if($s->rowCount()!==1)throw new RuntimeException('Staff member not found or cannot be modified.');flash('Staff member updated.');}elseif($action==='remove'){$id=(int)$_POST['id'];$s=$pdo->prepare("UPDATE users SET status='disabled' WHERE id=? AND business_id=? AND role NOT IN ('owner','admin','super_admin')");$s->execute([$id,$b['id']]);if($s->rowCount()!==1)throw new RuntimeException('Staff member not found or cannot be removed.');flash('Staff member removed from active staff.');}}catch(Throwable $e){flash('Could not update staff: '.$e->getMessage(),'error');}redirect('staff.php');}
$s=$pdo->prepare("SELECT id,name,email,role,status,created_at FROM users WHERE business_id=? AND role NOT IN ('owner','admin','super_admin') ORDER BY status ASC,id DESC");$s->execute([$b['id']]);$staff=$s->fetchAll();$roles=['manager','cashier','kitchen','reception','housekeeping','maintenance','waiter','runner','staff'];include __DIR__.'/app/layout_top.php';?>
<div class="topbar"><div><div class="eyebrow">Team</div><div class="title">Staff & permissions</div><div class="muted">Add, change roles, disable or restore staff accounts.</div></div></div><div class="split"><section class="panel"><h3>Add staff</h3><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="create"><label>Name<input name="name" required></label><br><label>Email<input name="email" type="email" required></label><br><label>Password<input name="password" type="password" minlength="8" required></label><br><label>Role<select name="role"><?php foreach($roles as $r):?><option value="<?=e($r)?>"><?=e(ucwords(str_replace('_',' ',$r)))?></option><?php endforeach;?></select></label><br><button class="btn gold">Create account</button></form></section><section class="panel"><h3>Team</h3><?php foreach($staff as $x):?><div class="row" style="align-items:flex-start"><div style="flex:1"><b><?=e($x['name'])?></b><div class="small muted"><?=e($x['email'])?></div><span class="badge"><?=e(strtoupper($x['status']))?></span></div><form method="post" style="min-width:180px"><?=csrf_field()?><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=$x['id']?>"><select name="role" style="margin:0"><?php foreach($roles as $r):?><option value="<?=e($r)?>" <?=$x['role']===$r?'selected':''?>><?=e(ucwords(str_replace('_',' ',$r)))?></option><?php endforeach;?></select><select name="status"><option value="active" <?=$x['status']==='active'?'selected':''?>>Active</option><option value="disabled" <?=$x['status']==='disabled'?'selected':''?>>Disabled</option></select><div class="actions"><button class="btn gold">Save</button><?php if($x['status']==='active'):?><button class="btn" type="submit" formaction="staff.php" name="action" value="remove" onclick="return confirm('Remove this staff member from active staff? Their history will be preserved.')">Remove</button><?php endif;?></div></form></div><?php endforeach;if(!$staff):?><p class="muted">No staff members yet.</p><?php endif;?></section></div><?php include __DIR__.'/app/layout_bottom.php';